CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_845" s="T228.TIE0.6" e="T228.TIE0.7">in</ts><nts n="HIAT:ip" id="Seg_846"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_848" s="T228.TIE0.7" e="T228.TIE0.8">der</ts><nts n="HIAT:ip" id="Seg_849"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_851" s="T228.TIE0.8" e="T229">Sendung</ts><nts n="HIAT:ip" id="Seg_852">.</nts><nts n="HIAT:ip" id="Seg_853"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_855" s="T229" e="T231"><ts n="HIAT:w" id="Seg_857" s="T229" e="T229.TIE0.1">Danke</ts><nts n="HIAT:ip" id="Seg_858"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_860" s="T229.TIE0.1" e="T229.TIE0.2">zunächst</ts><nts n="HIAT:ip" id="Seg_861"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_863" s="T229.TIE0.2" e="T230">mal</ts><nts n="HIAT:ip" id="Seg_864">,</nts><nts n="HIAT:ip" id="Seg_865"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_867" s="T230" e="T230.TIE0.1">dass</ts><nts n="HIAT:ip" id="Seg_868"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_870" s="T230.TIE0.1" e="T230.TIE0.2">Sie</ts><nts n="HIAT:ip" id="Seg_871"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_873" s="T230.TIE0.2" e="T230.TIE0.3">bei</ts><nts n="HIAT:ip" id="Seg_874"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_876" s="T230.TIE0.3" e="T230.TIE0.4">uns</ts><nts n="HIAT:ip" id="Seg_877"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_879" s="T230.TIE0.4" e="T231">sind</ts><nts n="HIAT:ip" id="Seg_880">.</nts><nts n="HIAT:ip" id="Seg_881"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_883" s="T231" e="T232"><ts n="HIAT:w" id="Seg_885" s="T231" e="T231.TIE0.1">Vielen</ts><nts n="HIAT:ip" id="Seg_886"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_888" s="T231.TIE0.1" e="T231.TIE0.2">Dank</ts><nts n="HIAT:ip" id="Seg_889">,</nts><nts n="HIAT:ip" id="Seg_890"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_892" s="T231.TIE0.2" e="T231.TIE0.3">dass</ts><nts n="HIAT:ip" id="Seg_893"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_895" s="T231.TIE0.3" e="T231.TIE0.4">Sie</ts><nts n="HIAT:ip" id="Seg_896"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_898" s="T231.TIE0.4" e="T231.TIE0.5">ihren</ts><nts n="HIAT:ip" id="Seg_899"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_901" s="T231.TIE0.5" e="T231.TIE0.6">Vorschlag</ts><nts n="HIAT:ip" id="Seg_902"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_904" s="T231.TIE0.6" e="T231.TIE0.7">noch</ts><nts n="HIAT:ip" id="Seg_905"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_907" s="T231.TIE0.7" e="T231.TIE0.8">mal</ts><nts n="HIAT:ip" id="Seg_908"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_910" s="T231.TIE0.8" e="T231.TIE0.9">richtig</ts><nts n="HIAT:ip" id="Seg_911"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_913" s="T231.TIE0.9" e="T232">geschildert</ts><nts n="HIAT:ip" id="Seg_914">…</nts><nts n="HIAT:ip" id="Seg_915"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE0"><ts n="sc" id="Seg_916" s="T0" e="T3"><ts n="e" id="Seg_918" s="T0" e="T1">Nah/ CDU-Nahen oder der CDU-nahen Studentenverbindung </ts><ts n="e" id="Seg_920" s="T1" e="T2">des RCDS ist, </ts><ts n="e" id="Seg_922" s="T2" e="T3">das ist Gottfried Ludewig, herzlich willkommen! </ts></ts><ts n="sc" id="Seg_923" s="T5" e="T20"><ts n="e" id="Seg_925" s="T5" e="T6">Sie sind nicht nur Vorsitzender des </ts><ts n="e" id="Seg_927" s="T6" e="T7">RCDS, Sie sind auch CDU-Mitglied, </ts><ts n="e" id="Seg_929" s="T7" e="T8">auch das muss man wissen, wenn man sich jetzt Ihren Vorschlag anhört. </ts><ts n="e" id="Seg_931" s="T8" e="T9">Sie haben nämlich gesagt, und damit sich ratzfatz auf Seite eins katapultiert </ts><ts n="e" id="Seg_933" s="T9" e="T10">((atmen)), dass man das Wahlrecht ändern sollten. </ts><ts n="e" id="Seg_935" s="T10" e="T11">Sie haben gesagt, </ts><ts n="e" id="Seg_937" s="T11" e="T12">((atmen 0,7s)) </ts><ts n="e" id="Seg_939" s="T12" e="T13">für diejenigen, die arbeiten, solle es ein doppeltes </ts><ts n="e" id="Seg_941" s="T13" e="T14">Wahlrecht geben, </ts><ts n="e" id="Seg_943" s="T14" e="T15">alle anderen haben nur ein einfaches Wahlrecht. </ts><ts n="e" id="Seg_945" s="T15" e="T16">Sagen Sie das… </ts><ts n="e" id="Seg_947" s="T16" e="T17">((1,3s)) </ts><ts n="e" id="Seg_949" s="T17" e="T18">Sagen Sie das ((0,5s)), um Arbeitslosen </ts><ts n="e" id="Seg_951" s="T18" e="T19">einen Anreiz zu geben, </ts><ts n="e" id="Seg_953" s="T19" e="T20">sich wieder n Job zu suchen? </ts></ts><ts n="sc" id="Seg_954" s="T37" e="T45"><ts n="e" id="Seg_956" s="T37" e="T38">Ich will </ts><ts n="e" id="Seg_958" s="T38" e="T39">kurz bei der </ts><ts n="e" id="Seg_960" s="T39" e="T40">Wahl</ts><ts n="e" id="Seg_962" s="T40" e="T41">rechtsä</ts><ts n="e" id="Seg_964" s="T41" e="T42">nderung bleiben. </ts><ts n="e" id="Seg_966" s="T42" e="T43">Sie haben gesagt, doppeltes Wahlrecht für diejenigen, die arbeiten, </ts><ts n="e" id="Seg_968" s="T43" e="T44">die Sie als Leis</ts><ts n="e" id="Seg_970" s="T44" e="T45">tungsträger verstehn. </ts></ts><ts n="sc" id="Seg_971" s="T48" e="T50"><ts n="e" id="Seg_973" s="T48" e="T49">Gut, bleiben wir bei den Leitungs </ts><ts n="e" id="Seg_975" s="T49" e="T50">trägern. </ts></ts><ts n="sc" id="Seg_976" s="T63" e="T70"><ts n="e" id="Seg_978" s="T63" e="T64">Herr Ludewig, ich würde gerne noch</ts><ts n="e" id="Seg_980" s="T64" e="T65"> kurz bei dem Wahlrecht bleiben, </ts><ts n="e" id="Seg_982" s="T65" e="T66">dass wirs verstehen. </ts><ts n="e" id="Seg_984" s="T66" e="T67">((0,4s)) Sie wollen also dokumentiert sehen, </ts><ts n="e" id="Seg_986" s="T67" e="T68">dass die Stimme eines Arbeitslosen </ts><ts n="e" id="Seg_988" s="T68" e="T69">und auch die eines Rentners </ts><ts n="e" id="Seg_990" s="T69" e="T70">den zählen Sie nämlich nicht zu den Leistungsträgern, dass die weniger Wert ist. </ts></ts><ts n="sc" id="Seg_991" s="T76" e="T80"><ts n="e" id="Seg_993" s="T76" e="T77">Also Sie hattens nicht </ts><ts n="e" id="Seg_995" s="T77" e="T78">ernst gemeint, Sie woll</ts><ts n="e" id="Seg_997" s="T78" e="T79">ten nur auf die Seite ein</ts><ts n="e" id="Seg_999" s="T79" e="T80">s. </ts></ts><ts n="sc" id="Seg_1000" s="T97" e="T98"><ts n="e" id="Seg_1002" s="T97" e="T98">Wie viel positive Rückmeldungen haben Sie denn innerhalb der Partei bekomm? </ts></ts><ts n="sc" id="Seg_1003" s="T115" e="T122"><ts n="e" id="Seg_1005" s="T115" e="T116">Herr Geissler, </ts><ts n="e" id="Seg_1007" s="T116" e="T117">((1,3s)) </ts><ts n="e" id="Seg_1009" s="T117" e="T118">wie beeindruckt sind Sie vom Vorschlag </ts><ts n="e" id="Seg_1011" s="T118" e="T119">Ihres jungen Parteifreundes? </ts><ts n="e" id="Seg_1013" s="T119" e="T122">((lacht)) </ts></ts><ts n="sc" id="Seg_1014" s="T176" e="T177"><ts n="e" id="Seg_1016" s="T176" e="T177">Der Reihe… </ts></ts><ts n="sc" id="Seg_1017" s="T185" e="T186"><ts n="e" id="Seg_1019" s="T185" e="T186">Herr Westerwelle! </ts></ts><ts n="sc" id="Seg_1020" s="T202" e="T205"><ts n="e" id="Seg_1022" s="T202" e="T203">Herr Ludewig, </ts><ts n="e" id="Seg_1024" s="T203" e="T204">((0,9s)) </ts><ts n="e" id="Seg_1026" s="T204" e="T205">dass wär wirklich dumm gelaufen, als Vorsitzender eine Studentenverbindung. </ts></ts><ts n="sc" id="Seg_1027" s="T209" e="T213"><ts n="e" id="Seg_1029" s="T209" e="T210">Erst mal </ts><ts n="e" id="Seg_1031" s="T210" e="T211">haben wir ja </ts><ts n="e" id="Seg_1033" s="T211" e="T212">Ihn </ts><ts n="e" id="Seg_1035" s="T212" e="T213">geglaubt. </ts></ts><ts n="sc" id="Seg_1036" s="T226" e="T232"><ts n="e" id="Seg_1038" s="T226" e="T227">Wir suchen nach anderen An</ts><ts n="e" id="Seg_1040" s="T227" e="T228">tworten. </ts><ts n="e" id="Seg_1042" s="T228" e="T229">das machen wir jetzt nämlich weiter in der Sendung. </ts><ts n="e" id="Seg_1044" s="T229" e="T230">Danke zunächst mal, </ts><ts n="e" id="Seg_1046" s="T230" e="T231">dass Sie bei uns sind. </ts><ts n="e" id="Seg_1048" s="T231" e="T232">Vielen Dank, dass Sie ihren Vorschlag noch mal richtig geschildert… </ts></ts></segmentation><annotation name="en" tierref="TIE5"><ta id="Seg_1049" s="T0" e="T3">Near / CDU-affiliated or the CDU-affiliated student fraternity of the RCDS is , that is Gottfried Ludewig , welcome ! </ta><ta id="Seg_1050" s="T5" e="T8">You are not only the chairman of the RCDS, you are also a member of the CDU, which is also important to know when listening to your proposal. </ta><ta id="Seg_1051" s="T8" e="T10">You have said, and thus catapulted yourself onto page one, that voting rights should be changed. </ta><ta id="Seg_1052" s="T10" e="T15">You said that those who work should have double voting rights, while everyone else should only have single voting rights. </ta><ta id="Seg_1053" s="T15" e="T16">Do you say that ... </ta><ta id="Seg_1054" s="T16" e="T20">Do you say that to give the unemployed an incentive to look for a job again? </ta><ta id="Seg_1055" s="T37" e="T42">I want to stay briefly with the change in voting rights . </ta><ta id="Seg_1056" s="T42" e="T45">You said , double voting rights for those who work , which you understand as a high achievers. </ta><ta id="Seg_1057" s="T48" e="T50">Well, let's stay with the line carriers.</ta><ta id="Seg_1058" s="T63" e="T66">Mr Ludewig, I would like to stay with the right to vote for a moment so that we understand. </ta><ta id="Seg_1059" s="T66" e="T70">So you want to see documented that the vote of an unemployed person and also that of a pensioner, whom you do not count among the top performers, is worth less. </ta><ta id="Seg_1060" s="T76" e="T80">So you didn't mean it seriously, you just wanted to be on page one. </ta><ta id="Seg_1061" s="T97" e="T98">How much positive feedback have you received within the party? </ta><ta id="Seg_1062" s="T115" e="T119">Mr Geissler, how impressed are you by your young party colleague's proposal? </ta><ta id="Seg_1063" s="T176" e="T177">The series ...</ta><ta id="Seg_1064" s="T185" e="T186">Mr Westerwelle ! </ta><ta id="Seg_1065" s="T202" e="T205">Mr Ludewig, that would have been really stupid as chairman of a student fraternity. </ta><ta id="Seg_1066" s="T209" e="T213">First of all, we believed him. </ta><ta id="Seg_1067" s="T226" e="T229">We are looking for other answers . that's what we are doing now in the programme . </ta><ta id="Seg_1068" s="T229" e="T231">Firstly, thank you for being with us . </ta><ta id="Seg_1069" s="T231" e="T232">Thank you for correctly describing your proposal once again ...</ta></annotation></segmented-tier><segmented-tier id="TIE1" speaker="SPK1" category="v" type="t" display-name="GL [v]"><timeline-fork start="T21" end="T22"><tli id="T21.TIE1.1"/>
