Seg_3330">)</nts><nts n="HIAT:ip" id="Seg_3331"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3333" s="T224" e="T224.TIE1.1">Ich</ts><nts n="HIAT:ip" id="Seg_3334"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3336" s="T224.TIE1.1" e="T224.TIE1.2">sehe</ts><nts n="HIAT:ip" id="Seg_3337"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3339" s="T224.TIE1.2" e="T224.TIE1.3">aber</ts><nts n="HIAT:ip" id="Seg_3340"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3342" s="T224.TIE1.3" e="T224.TIE1.4">diese</ts><nts n="HIAT:ip" id="Seg_3343"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3345" s="T224.TIE1.4" e="T224.TIE1.5">Antworten</ts><nts n="HIAT:ip" id="Seg_3346"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3348" s="T224.TIE1.5" e="T225">nich</ts><nts n="HIAT:ip" id="Seg_3349">.</nts><nts n="HIAT:ip" id="Seg_3350"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_3352" s="T225" e="T238"><nts n="HIAT:ip" id="Seg_3353">(</nts><nts n="HIAT:ip" id="Seg_3354">(</nts><ats n="HIAT:non-pho" id="Seg_3355" s="T225" e="T225.TIE1.1">0,2s</ats><nts n="HIAT:ip" id="Seg_3356">)</nts><nts n="HIAT:ip" id="Seg_3357">)</nts><nts n="HIAT:ip" id="Seg_3358"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3360" s="T225.TIE1.1" e="T225.TIE1.2">Wo</ts><nts n="HIAT:ip" id="Seg_3361"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3363" s="T225.TIE1.2" e="T225.TIE1.3">is</ts><nts n="HIAT:ip" id="Seg_3364"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3366" s="T225.TIE1.3" e="T225.TIE1.4">es</ts><nts n="HIAT:ip" id="Seg_3367"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3369" s="T225.TIE1.4" e="T238">denn</ts><nts n="HIAT:ip" id="Seg_3370">…</nts><nts n="HIAT:ip" id="Seg_3371"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_3373" s="T238" e="T227"><ts n="HIAT:w" id="Seg_3375" s="T238" e="T226">Nei</ts><nts n="HIAT:ip" id="Seg_3376"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3378" s="T226" e="T226.TIE1.1">n</ts><nts n="HIAT:ip" id="Seg_3379">,</nts><nts n="HIAT:ip" id="Seg_3380"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3382" s="T226.TIE1.1" e="T226.TIE1.2">ganz</ts><nts n="HIAT:ip" id="Seg_3383"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3385" s="T226.TIE1.2" e="T226.TIE1.3">kurz</ts><nts n="HIAT:ip" id="Seg_3386"><![CDATA[ ]]></nts><nts n="HIAT:ip" id="Seg_3387">(</nts><nts n="HIAT:ip" id="Seg_3388">(</nts><ats n="HIAT:non-pho" id="Seg_3389" s="T226.TIE1.3" e="T227">unv.</ats><nts n="HIAT:ip" id="Seg_3390">)</nts><nts n="HIAT:ip" id="Seg_3391">)</nts><nts n="HIAT:ip" id="Seg_3392">˙</nts><nts n="HIAT:ip" id="Seg_3393"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_3395" s="T227" e="T229"><ts n="HIAT:w" id="Seg_3397" s="T227" e="T227.TIE1.1">Wo</ts><nts n="HIAT:ip" id="Seg_3398"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3400" s="T227.TIE1.1" e="T227.TIE1.2">ist</ts><nts n="HIAT:ip" id="Seg_3401"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3403" s="T227.TIE1.2" e="T228">denn</ts><nts n="HIAT:ip" id="Seg_3404"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3406" s="T228" e="T228.TIE1.1">wo</ts><nts n="HIAT:ip" id="Seg_3407"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3409" s="T228.TIE1.1" e="T228.TIE1.2">is</ts><nts n="HIAT:ip" id="Seg_3410"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3412" s="T228.TIE1.2" e="T228.TIE1.3">denn</ts><nts n="HIAT:ip" id="Seg_3413"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3415" s="T228.TIE1.3" e="T228.TIE1.4">in</ts><nts n="HIAT:ip" id="Seg_3416"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3418" s="T228.TIE1.4" e="T228.TIE1.5">der</ts><nts n="HIAT:ip" id="Seg_3419"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3421" s="T228.TIE1.5" e="T228.TIE1.6">Bildungspolitik</ts><nts n="HIAT:ip" id="Seg_3422"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3424" s="T228.TIE1.6" e="T228.TIE1.7">diese</ts><nts n="HIAT:ip" id="Seg_3425"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_3427" s="T228.TIE1.7" e="T229">Antwort</ts><nts n="HIAT:ip" id="Seg_3428">?</nts><nts n="HIAT:ip" id="Seg_3429"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE1"><ts n="sc" id="Seg_3430" s="T3" e="T4"><ts n="e" id="Seg_3432" s="T3" e="T4">Hallo.</ts></ts><ts n="sc" id="Seg_3433" s="T20" e="T37"><ts n="e" id="Seg_3435" s="T20" e="T21">((atmen 1,2s)) </ts><ts n="e" id="Seg_3437" s="T21" e="T22">Momen, also erstmal in der Bildzeitung stand das so. </ts><ts n="e" id="Seg_3439" s="T22" e="T23">Ich hab n Brief geschrieben an die Vorsitzende der Vereinigung der CDU </ts><ts n="e" id="Seg_3441" s="T23" e="T24">in dem ich geschrieben habe, dass irgendwie </ts><ts n="e" id="Seg_3443" s="T24" e="T25">aus meiner Sicht die Balance in diesem Land n bisschen auseinander kommt. </ts><ts n="e" id="Seg_3445" s="T25" e="T26">Wir habens früher geschaft, die letzte Generation, </ts><ts n="e" id="Seg_3447" s="T26" e="T27">hier n Sozialstaat zu etablieren, </ts><ts n="e" id="Seg_3449" s="T27" e="T28">der gut funktioniert hat. </ts><ts n="e" id="Seg_3451" s="T28" e="T29">Der funktioniert aber nur, wenn die Leistungsträger, </ts><ts n="e" id="Seg_3453" s="T29" e="T30">also die Menschen die arbeiten gehen, </ts><ts n="e" id="Seg_3455" s="T30" e="T31">diesen Sozialstaat auch weiter finanzieren können. </ts><ts n="e" id="Seg_3457" s="T31" e="T32">Und da hab ich dann geschrieben, natürlich auch etwas provokant, </ts><ts n="e" id="Seg_3459" s="T32" e="T33">eh, jung, hab ich geschrieben, wir könnten doch mal über das Wahlrecht nachdenken. </ts><ts n="e" id="Seg_3461" s="T33" e="T34">Aber vor allem (um) den innerparteilichen, </ts><ts n="e" id="Seg_3463" s="T34" e="T35">eigentlich gar keinen öffentlichen, so vor allem innerparteilichen </ts><ts n="e" id="Seg_3465" s="T35" e="T36">Diskurs anzufangen darüber, was machen wir eigentlich </ts><ts n="e" id="Seg_3467" s="T36" e="T37">für Leistungsträger? </ts></ts><ts n="sc" id="Seg_3468" s="T38" e="T39"><ts n="e" id="Seg_3470" s="T38" e="T39">Was? </ts></ts><ts n="sc" id="Seg_3471" s="T40" e="T41"><ts n="e" id="Seg_3473" s="T40" e="T41">Ja. </ts></ts><ts n="sc" id="Seg_3474" s="T44" e="T49"><ts n="e" id="Seg_3476" s="T44" e="T45">Ich hab geschrieben "Leistungstr</ts><ts n="e" id="Seg_3478" s="T45" e="T46">äger". </ts><ts n="e" id="Seg_3480" s="T46" e="T47">Die Bildzeitung hat geschrieben, für die Leute die arbeiten. </ts><ts n="e" id="Seg_3482" s="T47" e="T48">Also s is schon Untersch </ts><ts n="e" id="Seg_3484" s="T48" e="T49">ied, was die Bildzeitung auf Seite eins </ts></ts><ts n="sc" id="Seg_3485" s="T50" e="T64"><ts n="e" id="Seg_3487" s="T50" e="T51">Die Leistungsträger in dieser Gesellschaft, die Familien die arbeiten gehen, </ts><ts n="e" id="Seg_3489" s="T51" e="T52">((atmen)) die, die Steuern zahlen, </ts><ts n="e" id="Seg_3491" s="T52" e="T53">die trotzdem, obwohl sie zwa zwei Verdiener sind, </ts><ts n="e" id="Seg_3493" s="T53" e="T54">den Spitzensteuersatz zahlen in dieser Bundesrepublik, sie zahlen nämlich die Spitzenmanager, </ts><ts n="e" id="Seg_3495" s="T54" e="T55">wir haben ja keinen Spitzensteuersatz ab hundertundfünfzigtausend Euro. </ts><ts n="e" id="Seg_3497" s="T55" e="T56">Und auch wenn Herr Heil, nur ganz kurz, </ts><ts n="e" id="Seg_3499" s="T56" e="T57">vorhin immer gesagt hat, wir diskutieren das hier falsch. </ts><ts n="e" id="Seg_3501" s="T57" e="T58">Wir diskutieren </ts><ts n="e" id="Seg_3503" s="T58" e="T59">die gesamte Zeit immer nur aus den alt hergebrachten Positionen und sagt, </ts><ts n="e" id="Seg_3505" s="T59" e="T60">wir müssen darüber diskutueren, wie wir Armut verhindern können, </ts><ts n="e" id="Seg_3507" s="T60" e="T61">frag ich mich, wo sind denn die Maßnahmen? </ts><ts n="e" id="Seg_3509" s="T61" e="T62">Also die Betreuungsrelation an den Universitäten ist immer noch schlecht </ts><ts n="e" id="Seg_3511" s="T62" e="T63">die Betreuungsrelation </ts><ts n="e" id="Seg_3513" s="T63" e="T64">an den Schulen auch. </ts></ts><ts n="sc" id="Seg_3514" s="T70" e="T96"><ts n="e" id="Seg_3516" s="T70" e="T71">Ich möchte eine Debatte anfangen in der CDU, darüber wie wir diese Leistungsträger stärken. </ts><ts n="e" id="Seg_3518" s="T71" e="T72">Ich hab das nicht so geschrieben, wie es in der Bildzeitung steht, ich habe geschrieben, </ts><ts n="e" id="Seg_3520" s="T72" e="T73">lasst uns darüber nachdenken, </ts><ts n="e" id="Seg_3522" s="T73" e="T74">lasst uns, nein, lasst uns darüber nachdenken, </ts><ts n="e" id="Seg_3524" s="T74" e="T75">wie wir diesen Sozialstaat überhaupt noch finanzieren können. </ts><ts n="e" id="Seg_3526" s="T75" e="T76">Es ist doch, wir machen doch immer </ts><ts n="e" id="Seg_3528" s="T76" e="T77">den zweiten… </ts><ts n="e" id="Seg_3530" s="T77" e="T78">Ganz kurz… </ts><ts n="e" id="Seg_3532" s="T78" e="T79">Nein, nein! </ts><ts n="e" id="Seg_3534" s="T79" e="T80">Ich woll</ts><ts n="e" id="Seg_3536" s="T80" e="T81">te eine Debatte anfangen, </ts><ts n="e" id="Seg_3538" s="T81" e="T82">darüber… </ts><ts n="e" id="Seg_3540" s="T82" e="T83">Wir ma</ts><ts n="e" id="Seg_3542" s="T83" e="T84">chen eine zwei… </ts><ts n="e" id="Seg_3544" s="T84" e="T85">((0,9s)) </ts><ts n="e" id="Seg_3546" s="T85" e="T86">Wir machen doch hier </ts><ts n="e" id="Seg_3548" s="T86" e="T87">den zweiten Schritt </ts><ts n="e" id="Seg_3550" s="T87" e="T88">vor dem ersten Schritt. </ts><ts n="e" id="Seg_3552" s="T88" e="T89">Denn zwar, wir verteilen die gesamte Zeit </ts><ts n="e" id="Seg_3554" s="T89" e="T90">Gelder um ((0,2s)) in dieser Gesellschaft, </ts><ts n="e" id="Seg_3556" s="T90" e="T91">diskutieren aber nicht darüber, </ts><ts n="e" id="Seg_3558" s="T91" e="T92">wie wir im ersten Schritt diese Gelder einholn, </ts><ts n="e" id="Seg_3560" s="T92" e="T93">bei den Leuten, die arbeiten gehen. </ts><ts n="e" id="Seg_3562" s="T93" e="T94">Und darüber eine Debatte zu starten, </ts><ts n="e" id="Seg_3564" s="T94" e="T95">dass war das Ziel innerhalb der Partei. </ts><ts n="e" id="Seg_3566" s="T95" e="T96">Dass es nachher bei der Bildzeitung auf Seite eins gekommen is, </ts></ts><ts n="sc" id="Seg_3567" s="T98" e="T115"><ts n="e" id="Seg_3569" s="T98" e="T99">Sie glauben gar nich, </ts><ts n="e" id="Seg_3571" s="T99" e="T100">vor allem, ehrlich gesagt, von Leuten, </ts><ts n="e" id="Seg_3573" s="T100" e="T101">von Bürgern, die mir, uns, geschrieben haben, </ts><ts n="e" id="Seg_3575" s="T101" e="T102">hab ich auch Emails bekommen, </ts><ts n="e" id="Seg_3577" s="T102" e="T103">die geschrieben haben, es reicht mir, dass die gesamte Zeit über </ts><ts n="e" id="Seg_3579" s="T103" e="T104">Hartz vier Sätze diskut</ts><ts n="e" id="Seg_3581" s="T104" e="T105">iert wird … </ts><ts n="e" id="Seg_3583" s="T105" e="T106">Was macht </ts><ts n="e" id="Seg_3585" s="T106" e="T107">man eigentlich mit den, was macht man eigentlich mit </ts><ts n="e" id="Seg_3587" s="T107" e="T108">den einfachen Bürgern, die arbeiten gehen? </ts><ts n="e" id="Seg_3589" s="T108" e="T109">((0,3s)) </ts><ts n="e" id="Seg_3591" s="T109" e="T236">Ja? </ts><ts n="e" id="Seg_3593" s="T236" e="T110">Und und machen Sie weiter. </ts><ts n="e" id="Seg_3595" s="T110" e="T111">Natürlich auch kritische Rückmeldung. </ts><ts n="e" id="Seg_3597" s="T111" e="T112">Aber viele, die auch gefragt haben, </ts><ts n="e" id="Seg_3599" s="T112" e="T113">wo setzen wir eigentlich die Schwerpunkte in diesem Land? </ts><ts n="e" id="Seg_3601" s="T113" e="T114">Setzen wir sie bei den Leuten die arbeiten oder bei den Leuten, </ts><ts n="e" id="Seg_3603" s="T114" e="T115">die eben nicht arbeiten gehen. </ts></ts><ts n="sc" id="Seg_3604" s="T125" e="T126"><ts n="e" id="Seg_3606" s="T125" e="T126">Fünfundzwanzig. </ts></ts><ts n="sc" id="Seg_3607" s="T139" e="T142"><ts n="e" id="Seg_3609" s="T139" e="T140">Ja, aber </ts><ts n="e" id="Seg_3611" s="T140" e="T141">bei aller </ts><ts n="e" id="Seg_3613" s="T141" e="T142">Achtung … </ts></ts><ts n="sc" id="Seg_3614" s="T174" e="T184"><ts n="e" id="Seg_3616" s="T174" e="T175">Das hat ja </ts><ts n="e" id="Seg_3618" s="T175" e="T176">Das hat ja, aber, ent</ts><ts n="e" id="Seg_3620" s="T176" e="T177">schuldigung, </ts><ts n="e" id="Seg_3622" s="T177" e="T178">Herr Geissler, Herr Geissler </ts><ts n="e" id="Seg_3624" s="T178" e="T179">wenn, also, man muss sich nicht mit dem idiotischen Vorschlag im einzelnen auseinander setzen. </ts><ts n="e" id="Seg_3626" s="T179" e="T180">Aber es ist schon so, wenn das Schule macht, </ts><ts n="e" id="Seg_3628" s="T180" e="T181">wenn der junge Unionvorsitzenden, den Älteren gleichzeitig nich das Hüftgelenk </ts><ts n="e" id="Seg_3630" s="T181" e="T182">((unv.)) will, dann ist das ne Denke, die dahinter steckt. </ts><ts n="e" id="Seg_3632" s="T182" e="T183">Und das macht mir schon Sorge. </ts><ts n="e" id="Seg_3634" s="T183" e="T184">Darüber müssen wir uns unterhalten. </ts></ts><ts n="sc" id="Seg_3635" s="T187" e="T188"><ts n="e" id="Seg_3637" s="T187" e="T188">Ja, genau wie er eben. </ts></ts><ts n="sc" id="Seg_3638" s="T189" e="T191"><ts n="e" id="Seg_3640" s="T189" e="T190">Aber offensichtlich ist das in we</ts><ts n="e" id="Seg_3642" s="T190" e="T191">((unv.)) an der Stelle. </ts></ts><ts n="sc" id="Seg_3643" s="T205" e="T211"><ts n="e" id="Seg_3645" s="T205" e="T206">Das wäre, das wäre wirklich dumm gelaufen, </ts><ts n="e" id="Seg_3647" s="T206" e="T207">wenn man der Bildzeitung immer so hunderfünfzigprozentig </ts><ts n="e" id="Seg_3649" s="T207" e="T208">glauben würde. </ts><ts n="e" id="Seg_3651" s="T208" e="T209">((atmen 0,2s)) </ts><ts n="e" id="Seg_3653" s="T209" e="T210">Ich wollte, </ts><ts n="e" id="Seg_3655" s="T210" e="T211">ich, ((0,6s)) </ts></ts><ts n="sc" id="Seg_3656" s="T212" e="T229"><ts n="e" id="Seg_3658" s="T212" e="T213">Ich wiederhole es noch mal. </ts><ts n="e" id="Seg_3660" s="T213" e="T214">((atmen 0,3s)) </ts><ts n="e" id="Seg_3662" s="T214" e="T215">Ich wollte einen Diskurs anstacheln und </ts><ts n="e" id="Seg_3664" s="T215" e="T216">dass man da mal provoziert und nach vorne geht </ts><ts n="e" id="Seg_3666" s="T216" e="T217">((atmen 0,3s)) </ts><ts n="e" id="Seg_3668" s="T217" e="T218">find ich, nach meiner Meinung, ist für junge Leute in Ordnung. </ts><ts n="e" id="Seg_3670" s="T218" e="T219">((atmen 0,2s)) </ts><ts n="e" id="Seg_3672" s="T219" e="T220">Man muss diesen Diskurs anfangen, Herr Heil </ts><ts n="e" id="Seg_3674" s="T220" e="T221">redet davon, dass wir unbedingt/ ganz kurz, </ts><ts n="e" id="Seg_3676" s="T221" e="T222">((atmen 0,2s)) </ts><ts n="e" id="Seg_3678" s="T222" e="T223">dass wir unbedingt andere Antworten finden müssen. </ts><ts n="e" id="Seg_3680" s="T223" e="T224">((atmen 0,3s)) </ts><ts n="e" id="Seg_3682" s="T224" e="T225">Ich sehe aber diese Antworten nich. </ts><ts n="e" id="Seg_3684" s="T225" e="T238">((0,2s)) Wo is es denn… </ts><ts n="e" id="Seg_3686" s="T238" e="T226">Nei </ts><ts n="e" id="Seg_3688" s="T226" e="T227">n, ganz kurz ((unv.))˙ </ts><ts n="e" id="Seg_3690" s="T227" e="T228">Wo ist denn </ts><ts n="e" id="Seg_3692" s="T228" e="T229">wo is denn in der Bildungspolitik diese Antwort? </ts></ts></segmentation><annotation name="en" tierref="TIE6"><ta id="Seg_3693" s="T3" e="T4">Hello .</ta><ta id="Seg_3694" s="T20" e="T22"> Wait , so first of all the Bild newspaper said so . </ta><ta id="Seg_3695" s="T22" e="T25"> I wrote a letter to the chairwoman of the CDU association in which I wrote that somehow, from my point of view, the balance in this country is a bit off. </ta><ta id="Seg_3696" s="T25" e="T28">We managed to establish a welfare state here in the past, the last generation, which worked well. </ta><ta id="Seg_3697" s="T28" e="T31">But it only works if the service providers, i.e. the people who go to work, can continue to finance this welfare state. </ta><ta id="Seg_3698" s="T31" e="T33">And then I wrote, somewhat provocatively of course, eh, young, I wrote that we could think about the right to vote. </ta><ta id="Seg_3699" s="T33" e="T37">But above all to start a discourse within the party, actually not a public discourse at all, especially within the party, about what we are actually doing for high achievers. </ta><ta id="Seg_3700" s="T38" e="T39">What ?</ta><ta id="Seg_3701" s="T40" e="T41">Yes .</ta><ta id="Seg_3702" s="T44" e="T46">I wrote "high achievers". </ta><ta id="Seg_3703" s="T46" e="T47">The Bild newspaper wrote , for the people who work . </ta><ta id="Seg_3704" s="T47" e="T49">So there's a difference in what the Bild newspaper wrote on page one.</ta><ta id="Seg_3705" s="T50" e="T55">The top performers in this society, the families who go to work, the ones who pay taxes, who nevertheless pay the top tax rate in this Federal Republic, even though they are two earners, because they pay the top managers, we do not have a top tax rate above one hundred and fifty thousand euros. </ta><ta id="Seg_3706" s="T55" e="T57">And even if Mr Heil, just very briefly, always said earlier that we are discussing this incorrectly here. </ta><ta id="Seg_3707" s="T57" e="T60">All the time we are only discussing from the old traditional positions and saying that we have to discuss how we can prevent poverty, I ask myself where are the measures? </ta><ta id="Seg_3708" s="T60" e="T64">Well, the student-teacher ratio at universities is still poor, as is the student-teacher ratio at schools. </ta><ta id="Seg_3709" s="T70" e="T71">I would like to start a debate in the CDU about how we can strengthen these high achievers. </ta><ta id="Seg_3710" s="T71" e="T75">I didn't write it the way it appears in the Bild newspaper, I wrote, let's think about it, let's, no, let's think about how we can still finance this welfare state at all. </ta><ta id="Seg_3711" s="T75" e="T77">It's true, we always do the second ... </ta><ta id="Seg_3712" s="T77" e="T78">Very briefly ... </ta><ta id="Seg_3713" s="T78" e="T79">No, no! </ta><ta id="Seg_3714" s="T79" e="T82">I wanted to start a debate about this ... </ta><ta id="Seg_3715" s="T82" e="T84">We're doing a second ... </ta><ta id="Seg_3716" s="T84" e="T88">We're taking the second step before the first step. </ta><ta id="Seg_3717" s="T88" e="T93">Because although we distribute money around in this society all the time, we don't discuss how we collect this money in the first step from the people who go to work. </ta><ta id="Seg_3718" s="T93" e="T95">And to start a debate about this was the goal within the party. </ta><ta id="Seg_3719" s="T95" e="T96">The fact that it later made it to page one of the Bild newspaper,</ta><ta id="Seg_3720" s="T98" e="T105">You don't believe it, especially, to be honest, from people who have written to me, to us, I have also received emails saying that I am fed up with the fact that Hartz four rates are being discussed all the time... </ta><ta id="Seg_3721" s="T105" e="T108">What do you actually do with the ordinary citizens who go out to work? </ta><ta id="Seg_3722" s="T108" e="T236">Yes ? </ta><ta id="Seg_3723" s="T236" e="T110">And and go on . </ta><ta id="Seg_3724" s="T110" e="T111"> Critical feedback, of course. </ta><ta id="Seg_3725" s="T111" e="T113">But many who have also asked where do we actually prioritise in this country? </ta><ta id="Seg_3726" s="T113" e="T115">Do we prioritise the people who work or the people who don't work? </ta><ta id="Seg_3727" s="T125" e="T126">Twenty-five . </ta><ta id="Seg_3728" s="T139" e="T142">Yes, but with all due respect ...</ta><ta id="Seg_3729" s="T174" e="T179">That's right, that's right, but, sorry, Mr Geissler, Mr Geissler if, well, you don't have to deal with the idiotic proposal in detail. </ta><ta id="Seg_3730" s="T179" e="T182">But it's true that if this sets a precedent, if the young Union chairman doesn't want the older person's hip joint at the same time, then that's the thinking behind it. </ta><ta id="Seg_3731" s="T182" e="T183">And that worries me . </ta><ta id="Seg_3732" s="T183" e="T184">We need to talk about that . </ta><ta id="Seg_3733" s="T187" e="T188">Yes, just like him. </ta><ta id="Seg_3734" s="T189" e="T191">But obviously this is in we at the point . </ta><ta id="Seg_3735" s="T205" e="T209">That would have been really stupid if you always believed the Bild newspaper one hundred and fifty per cent. </ta><ta id="Seg_3736" s="T209" e="T211">I wanted to , I ,</ta><ta id="Seg_3737" s="T212" e="T213">I'll repeat it again . </ta><ta id="Seg_3738" s="T213" e="T218"> I wanted to instigate a discourse and I think it's okay for young people to be provocative and go forward. </ta><ta id="Seg_3739" s="T218" e="T223">You have to start this discourse , Mr Heil talks about the fact that we absolutely / very briefly , that we absolutely have to find other answers . </ta><ta id="Seg_3740" s="T223" e="T225">But I don't see these answers . </ta><ta id="Seg_3741" s="T225" e="T238">Where is it... </ta><ta id="Seg_3742" s="T238" e="T227">No, very briefly ˙ </ta><ta id="Seg_3743" s="T227" e="T229">Where is this answer in education policy? </ta></annotation></segmented-tier><segmented-tier id="TIE2" speaker="SPK2" category="v" type="t" display-name="HG [v]"><timeline-fork start="T96" end="T97"><tli id="T96.TIE2.1"/>
