IE2.6">Hilfe</ts><nts n="HIAT:ip" id="Seg_4556">,</nts><nts n="HIAT:ip" id="Seg_4557"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4559" s="T169.TIE2.6" e="T169.TIE2.7">die</ts><nts n="HIAT:ip" id="Seg_4560"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4562" s="T169.TIE2.7" e="T169.TIE2.8">Solidarität</ts><nts n="HIAT:ip" id="Seg_4563"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4565" s="T169.TIE2.8" e="T169.TIE2.9">der</ts><nts n="HIAT:ip" id="Seg_4566"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4568" s="T169.TIE2.9" e="T169.TIE2.10">anderen</ts><nts n="HIAT:ip" id="Seg_4569"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4571" s="T169.TIE2.10" e="T170">brauchn</ts><nts n="HIAT:ip" id="Seg_4572">,</nts><nts n="HIAT:ip" id="Seg_4573"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4575" s="T170" e="T170.TIE2.1">gegen</ts><nts n="HIAT:ip" id="Seg_4576"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4578" s="T170.TIE2.1" e="T170.TIE2.2">die</ts><nts n="HIAT:ip" id="Seg_4579"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4581" s="T170.TIE2.2" e="T170.TIE2.3">anderen</ts><nts n="HIAT:ip" id="Seg_4582"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4584" s="T170.TIE2.3" e="T171">ausspielen</ts><nts n="HIAT:ip" id="Seg_4585">.</nts><nts n="HIAT:ip" id="Seg_4586"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_4588" s="T171" e="T174"><nts n="HIAT:ip" id="Seg_4589">(</nts><nts n="HIAT:ip" id="Seg_4590">(</nts><ats n="HIAT:non-pho" id="Seg_4591" s="T171" e="T172">atmen 0,3s</ats><nts n="HIAT:ip" id="Seg_4592">)</nts><nts n="HIAT:ip" id="Seg_4593">)</nts><nts n="HIAT:ip" id="Seg_4594"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4596" s="T172" e="T172.TIE2.1">Äh</ts><nts n="HIAT:ip" id="Seg_4597">,</nts><nts n="HIAT:ip" id="Seg_4598"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4600" s="T172.TIE2.1" e="T172.TIE2.2">eine</ts><nts n="HIAT:ip" id="Seg_4601"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4603" s="T172.TIE2.2" e="T172.TIE2.3">endsolidarisierte</ts><nts n="HIAT:ip" id="Seg_4604"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4606" s="T172.TIE2.3" e="T173">Gesellschaft</ts><nts n="HIAT:ip" id="Seg_4607"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4609" s="T173" e="T173.TIE2.1">läuft</ts><nts n="HIAT:ip" id="Seg_4610"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4612" s="T173.TIE2.1" e="T173.TIE2.2">ins</ts><nts n="HIAT:ip" id="Seg_4613"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4615" s="T173.TIE2.2" e="T174">Elend</ts><nts n="HIAT:ip" id="Seg_4616">.</nts><nts n="HIAT:ip" id="Seg_4617"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_4619" s="T174" e="T176"><ts n="HIAT:w" id="Seg_4621" s="T174" e="T175">Wir</ts><nts n="HIAT:ip" id="Seg_4622"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4624" s="T175" e="T175.TIE2.1">führn</ts><nts n="HIAT:ip" id="Seg_4625"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4627" s="T175.TIE2.1" e="T175.TIE2.2">alle</ts><nts n="HIAT:ip" id="Seg_4628"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4630" s="T175.TIE2.2" e="T176">zusammen</ts><nts n="HIAT:ip" id="Seg_4631">.</nts></ts></ts><ts n="sc" id="Seg_4632" s="T225" e="T238"><ts n="HIAT:u" id="Seg_4634" s="T225" e="T238"><ts n="HIAT:w" id="Seg_4636" s="T225" e="T225.TIE2.1">Aber</ts><nts n="HIAT:ip" id="Seg_4637"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4639" s="T225.TIE2.1" e="T225.TIE2.2">nich</ts><nts n="HIAT:ip" id="Seg_4640"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_4642" s="T225.TIE2.2" e="T238">falsch</ts><nts n="HIAT:ip" id="Seg_4643">.</nts><nts n="HIAT:ip" id="Seg_4644"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE2"><ts n="sc" id="Seg_4645" s="T96" e="T97"><ts n="e" id="Seg_4647" s="T96" e="T97">((unverständlich)) gibs nich nur … </ts></ts><ts n="sc" id="Seg_4648" s="T104" e="T106"><ts n="e" id="Seg_4650" s="T104" e="T105">Das ist ja was </ts><ts n="e" id="Seg_4652" s="T105" e="T106">anderes. </ts></ts><ts n="sc" id="Seg_4653" s="T120" e="T121"><ts n="e" id="Seg_4655" s="T120" e="T121">Also … </ts></ts><ts n="sc" id="Seg_4656" s="T122" e="T125"><ts n="e" id="Seg_4658" s="T122" e="T123">Ähm, ich meine mit, </ts><ts n="e" id="Seg_4660" s="T123" e="T237">ich weiß nich, wie al… </ts><ts n="e" id="Seg_4662" s="T237" e="T124">Wi/ wir/ wir haben uns vorhin schon unterhalten, </ts><ts n="e" id="Seg_4664" s="T124" e="T125">wie alt sind Sie denn? </ts></ts><ts n="sc" id="Seg_4665" s="T126" e="T140"><ts n="e" id="Seg_4667" s="T126" e="T127">Also mit fünfundzwanzig Jahren kann man schon ein mal </ts><ts n="e" id="Seg_4669" s="T127" e="T128">((0,4s)) </ts><ts n="e" id="Seg_4671" s="T128" e="T129">ähm, etwas </ts><ts n="e" id="Seg_4673" s="T129" e="T130">((1,0s)) </ts><ts n="e" id="Seg_4675" s="T130" e="T132">Unsinniges sagen. </ts><ts n="e" id="Seg_4677" s="T132" e="T134">Ähm, ich bin, ich bin froh, </ts><ts n="e" id="Seg_4679" s="T134" e="T135">äh, deswegen sollte man Sie nicht in die Pfanne haun. </ts><ts n="e" id="Seg_4681" s="T135" e="T136">((0,5s)) </ts><ts n="e" id="Seg_4683" s="T136" e="T137">Äh, ich bin froh, dass nicht alle wissen, was ich mit fünfundzwanzig </ts><ts n="e" id="Seg_4685" s="T137" e="T138">((0,3s)) </ts><ts n="e" id="Seg_4687" s="T138" e="T139">äh, gesagt habe, ne, dass will ich auch hinzu fü </ts><ts n="e" id="Seg_4689" s="T139" e="T140">gen. </ts></ts><ts n="sc" id="Seg_4690" s="T141" e="T176"><ts n="e" id="Seg_4692" s="T141" e="T142">Aber </ts><ts n="e" id="Seg_4694" s="T142" e="T143">aber, ähm, äh, wir dürfen eben </ts><ts n="e" id="Seg_4696" s="T143" e="T144">da natürlich nicht auf die Schulter klopfen </ts><ts n="e" id="Seg_4698" s="T144" e="T145">und sagen, Sie Sie haben was gescheites gesagt. </ts><ts n="e" id="Seg_4700" s="T145" e="T146">Das war nicht sehr gescheit. </ts><ts n="e" id="Seg_4702" s="T146" e="T147">((0,4s)) </ts><ts n="e" id="Seg_4704" s="T147" e="T148">Nich wahr? </ts><ts n="e" id="Seg_4706" s="T148" e="T149">((unv.)) Was machste mit de/ was machen Sie mit dem Opelarbeiter, </ts><ts n="e" id="Seg_4708" s="T149" e="T150">der, äh, nun plötzlich weil in Denfer Kolo Kolorado, nich wahr, </ts><ts n="e" id="Seg_4710" s="T150" e="T151">((stottert 1,5s))</ts><ts n="e" id="Seg_4712" s="T151" e="T152">der dortige Bord von General Motors </ts><ts n="e" id="Seg_4714" s="T152" e="T153">Mist gemacht hat und arbeitslos wird. </ts><ts n="e" id="Seg_4716" s="T153" e="T154">Also vorher zwei Stimmen. </ts><ts n="e" id="Seg_4718" s="T154" e="T155">Da wird er plötzlich arbeitslos, </ts><ts n="e" id="Seg_4720" s="T155" e="T156">hat er dann bei der nächsten Landtagswahl nur noch eine. </ts><ts n="e" id="Seg_4722" s="T156" e="T157">Also Sie kommen in unglauliche Schwierigkeiten, </ts><ts n="e" id="Seg_4724" s="T157" e="T158">((atmen 0,4s)) </ts><ts n="e" id="Seg_4726" s="T158" e="T159">Äh </ts><ts n="e" id="Seg_4728" s="T159" e="T160">((0,4s)) </ts><ts n="e" id="Seg_4730" s="T160" e="T161">der Grundansatz ist ja richtig. </ts><ts n="e" id="Seg_4732" s="T161" e="T162">Wir müssen natürlich eine Politik machen, </ts><ts n="e" id="Seg_4734" s="T162" e="T163">dass ist klar, </ts><ts n="e" id="Seg_4736" s="T163" e="T164">für diejenigen, </ts><ts n="e" id="Seg_4738" s="T164" e="T165">((atmen)) nich wahr, die die arbeiten, da is kein Gegensatz. </ts><ts n="e" id="Seg_4740" s="T165" e="T166">((atmen 0,3s))</ts><ts n="e" id="Seg_4742" s="T166" e="T167">Wir dürfen in dieser Gesellschaft nicht diejenigen, </ts><ts n="e" id="Seg_4744" s="T167" e="T168">die ein Arbeitsplatz verloren haben, </ts><ts n="e" id="Seg_4746" s="T168" e="T169">((atmen 0,4s)) </ts><ts n="e" id="Seg_4748" s="T169" e="T170">nich wahr, und die die Hilfe, die Solidarität der anderen brauchn, </ts><ts n="e" id="Seg_4750" s="T170" e="T171">gegen die anderen ausspielen. </ts><ts n="e" id="Seg_4752" s="T171" e="T172">((atmen 0,3s)) </ts><ts n="e" id="Seg_4754" s="T172" e="T173">Äh, eine endsolidarisierte Gesellschaft </ts><ts n="e" id="Seg_4756" s="T173" e="T174">läuft ins Elend. </ts><ts n="e" id="Seg_4758" s="T174" e="T175">Wir </ts><ts n="e" id="Seg_4760" s="T175" e="T176">führn alle zusammen.</ts></ts><ts n="sc" id="Seg_4761" s="T225" e="T238"><ts n="e" id="Seg_4763" s="T225" e="T238">Aber nich falsch. </ts></ts></segmentation><annotation name="en" tierref="TIE7"><ta id="Seg_4764" s="T96" e="T97"> there is not only ...</ta><ta id="Seg_4765" s="T104" e="T106">That's something else . </ta><ta id="Seg_4766" s="T120" e="T121">So ...</ta><ta id="Seg_4767" s="T122" e="T237">Erm , I mean by , I don't know how old ... </ta><ta id="Seg_4768" s="T237" e="T125">We / we / we were talking earlier , how old are you ? </ta><ta id="Seg_4769" s="T126" e="T132">So at the age of twenty-five you can say something nonsensical . </ta><ta id="Seg_4770" s="T132" e="T135">Um , I'm , I'm glad , uh , that's why you shouldn't be put in the pan . </ta><ta id="Seg_4771" s="T135" e="T140"> Er, I'm glad that not everyone knows what I said when I was twenty-five, er, well, I want to add that too. </ta><ta id="Seg_4772" s="T141" e="T145">But of course we mustn't pat ourselves on the back and say, "You said something clever". </ta><ta id="Seg_4773" s="T145" e="T146">That wasn't very clever. </ta><ta id="Seg_4774" s="T146" e="T148">Wasn't it? </ta><ta id="Seg_4775" s="T148" e="T153">What do you do with the Opel worker who, uh, suddenly because in Denfer Kolo Kolorado, isn't it, the local board of General Motors has messed up and becomes unemployed? </ta><ta id="Seg_4776" s="T153" e="T154">So two votes before . </ta><ta id="Seg_4777" s="T154" e="T156">Then he suddenly becomes unemployed and only has one vote in the next state election. </ta><ta id="Seg_4778" s="T156" e="T161">So you get into unbelievable difficulties, the basic approach is correct. </ta><ta id="Seg_4779" s="T161" e="T165">Of course we have to make a policy, that is clear, for those, not true, those who work, there is no contradiction. </ta><ta id="Seg_4780" s="T165" e="T171">In this society, we must not play off those who have lost a job against those who need the help and solidarity of others. </ta><ta id="Seg_4781" s="T171" e="T174">Uh , an end-solidarised society runs into misery . </ta><ta id="Seg_4782" s="T174" e="T176">We bring everyone together .</ta><ta id="Seg_4783" s="T225" e="T238">But not wrong . </ta></annotation></segmented-tier><segmented-tier id="TIE3" speaker="SPK3" category="v" type="t" display-name="GW [v]"><timeline-fork start="T190" end="T191"><tli id="T190.TIE3.1"/>
