e" id="Seg_4982" s="T190" e="T191">Leute, jetzt wolln ((unv.)) ers </ts><ts n="e" id="Seg_4984" s="T191" e="T192">jetzt wollen wir nicht aus jedem Studentenwitz ne Staatsaffaire machen, </ts><ts n="e" id="Seg_4986" s="T192" e="T193">an dieser Stelle hier. </ts><ts n="e" id="Seg_4988" s="T193" e="T194">Auch mal festhalten hier, an der Sache. </ts><ts n="e" id="Seg_4990" s="T194" e="T195">((atmen 0,4s)) </ts><ts n="e" id="Seg_4992" s="T195" e="T196">Ich meine, halbes Wahlrecht, </ts><ts n="e" id="Seg_4994" s="T196" e="T197">((atmen 0,3s)) </ts><ts n="e" id="Seg_4996" s="T197" e="T198">halbes Wahlrecht für Rentner, und das hieße dann ja auch, </ts><ts n="e" id="Seg_4998" s="T198" e="T199">((0,8s)) </ts><ts n="e" id="Seg_5000" s="T199" e="T200">Kollege, halbes Wahlrecht für Studenten. </ts><ts n="e" id="Seg_5002" s="T200" e="T201">Das wäre aber dumm gelaufen, oder? </ts></ts></segmentation><annotation name="en" tierref="TIE8"><ta id="Seg_5003" s="T190" e="T193">Guys, let's not turn every student joke into a state affair at this point here. </ta><ta id="Seg_5004" s="T193" e="T194"> Let's also stick to the point here . </ta><ta id="Seg_5005" s="T194" e="T200">I mean , half the right to vote , half the right to vote for pensioners , and that would then also mean , colleague , half the right to vote for students . </ta><ta id="Seg_5006" s="T200" e="T201">But that would have been stupid , wouldn't it ? </ta></annotation></segmented-tier><segmented-tier id="TIE4" category="nn" type="d" display-name="[nn]"><segmentation name="Event" tierref="TIE4"><ats n="e" id="Seg_5007" s="T3" e="T6">((applaudieren)) </ats><ats n="e" id="Seg_5008" s="T15" e="T18">((Lachen und Unruhe)) </ats><ats n="e" id="Seg_5009" s="T18" e="T19">((Lachen und Unruhe)) </ats><ats n="e" id="Seg_5010" s="T72" e="T73">((Lachen)) </ats><ats n="e" id="Seg_5011" s="T83" e="T88">((applaudieren)) </ats><ats n="e" id="Seg_5012" s="T132" e="T133">((lachen)) </ats><ats n="e" id="Seg_5013" s="T184" e="T189">((unverständlich)) </ats><ats n="e" id="Seg_5014" s="T201" e="T205">((Publikum lacht und applaudiert)) </ats></segmentation></segmented-tier></segmented-body><conversion-info><basic-transcription-conversion-info><conversion-timeline><conversion-tli id="T0"/><conversion-tli id="T1"/><conversion-tli id="T2"/><conversion-tli id="T3"/><conversion-tli id="T4"/><conversion-tli id="T5"/><conversion-tli id="T6"/><conversion-tli id="T7"/><conversion-tli id="T8"/><conversion-tli id="T9"/><conversion-tli id="T10"/><conversion-tli id="T11"/><conversion-tli id="T12"/><conversion-tli id="T13"/><conversion-tli id="T14"/><conversion-tli id="T15"/><conversion-tli id="T16"/><conversion-tli id="T17"/><conversion-tli id="T18"/><conversion-tli id="T19"/><conversion-tli id="T20"/><conversion-tli id="T21"/><conversion-tli id="T22"/><conversion-tli id="T23"/><conversion-tli id="T24"/><conversion-tli id="T25"/><conversion-tli id="T26"/><conversion-tli id="T27"/><conversion-tli id="T28"/><conversion-tli id="T29"/><conversion-tli id="T30"/><conversion-tli id="T31"/><conversion-tli id="T32"/><conversion-tli id="T33"/><conversion-tli id="T34"/><conversion-tli id="T35"/><conversion-tli id="T36"/><conversion-tli id="T37"/><conversion-tli id="T38"/><conversion-tli id="T39"/><conversion-tli id="T40"/><conversion-tli id="T41"/><conversion-tli id="T42"/><conversion-tli id="T43"/><conversion-tli id="T44"/><conversion-tli id="T45"/><conversion-tli id="T46"/><conversion-tli id="T47"/><conversion-tli id="T48"/><conversion-tli id="T49"/><conversion-tli id="T50"/><conversion-tli id="T51"/><conversion-tli id="T52"/><conversion-tli id="T53"/><conversion-tli id="T54"/><conversion-tli id="T55"/><conversion-tli id="T56"/><conversion-tli id="T57"/><conversion-tli id="T58"/><conversion-tli id="T59"/><conversion-tli id="T60"/><conversion-tli id="T61"/><conversion-tli id="T62"/><conversion-tli id="T63"/><conversion-tli id="T64"/><conversion-tli id="T65"/><conversion-tli id="T66"/><conversion-tli id="T67"/><conversion-tli id="T